{"recipients":["dba@test.local","ops@test.local","dev1@test.local"],"subject":"🚨 Patroni ETCD: Connection issues on {{ctx.results.0.aggregations.group_by_field.buckets.size}} node(s)","message":"<html><head><meta charset=\"utf-8\">
<style>body{font-family:Arial,Helvetica,sans-serif;color:#222;padding:10px}
.group-section{margin-bottom:25px;border:2px solid #c0392b;border-radius:5px;overflow:hidden}
.group-header{font-weight:bold;color:#fff;background:#c0392b;padding:12px 15px;font-size:16px}
.error-code-section{margin:10px;border:1px solid #ddd;border-radius:3px;overflow:hidden}
.error-code-header{font-weight:bold;color:#333;background:#f5f5f5;padding:8px 12px;font-size:14px;border-bottom:1px solid #ddd}
.log-container{background:#fff}
