.log-entry:nth-child(odd){background:#fff}
.log-entry:nth-child(even){background:#fff9f9}
.log-entry:last-child{border-bottom:none}
time{color:#666;font-size:11px;display:block;margin-bottom:4px}</style>
</head><body><h2 style=\"color:#c0392b;margin:0 0 15px 0\">🚨 Patroni ETCD Connection Alert</h2><p style=\"margin-bottom:20px\"><strong>Monitor:</strong> {{ctx.monitor.name}}<br/><strong>Trigger:</strong> {{ctx.trigger.name}}<br/><strong>Time Window:</strong> {{ctx.periodStart}} to {{ctx.periodEnd}}<br/><strong>Alert Condition:</strong> ETCD/DCS connection problems detected</p>{{#ctx.results.0.aggregations.group_by_field.buckets}}<div class=\"group-section\"><div class=\"group-header\">🔴 Node: {{key}} — {{doc_count}} error(s)</div><div class=\"log-container\">{{#top_entries.hits.hits}}<div class=\"log-entry\"><time>{{_source.@timestamp}}</time>{{{_source._raw}}}}</div>{{/top_entries.hits.hits}}</div></div>{{/ctx.results.0.aggregations.group_by_field.buckets}}</body></html>"}
